-- GENERATED by tools/dump_schema.py. The app also creates this itself on startup (RUN_MIGRATIONS=1).

CREATE TABLE audit (
	id BIGSERIAL NOT NULL, 
	ts VARCHAR(32) NOT NULL, 
	actor_id INTEGER, 
	action VARCHAR(30) NOT NULL, 
	outcome VARCHAR(10) NOT NULL, 
	target VARCHAR(64), 
	reason VARCHAR(100) NOT NULL, 
	ip VARCHAR(64) NOT NULL, 
	detail TEXT NOT NULL, 
	prev_hash VARCHAR(64) NOT NULL, 
	hash VARCHAR(64) NOT NULL, 
	PRIMARY KEY (id)
);

CREATE TABLE users (
	id SERIAL NOT NULL, 
	email VARCHAR(254) NOT NULL, 
	pw_hash VARCHAR(255) NOT NULL, 
	role VARCHAR(10) NOT NULL, 
	active BOOLEAN NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (email)
);

CREATE TABLE documents (
	id VARCHAR(32) NOT NULL, 
	owner_id INTEGER NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	category VARCHAR(50) NOT NULL, 
	storage_key VARCHAR(32) NOT NULL, 
	size BIGINT NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	deleted_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id), 
	UNIQUE (storage_key)
);

CREATE INDEX ix_documents_owner_id ON documents (owner_id);

CREATE TABLE sessions (
	id SERIAL NOT NULL, 
	token_hash VARCHAR(64) NOT NULL, 
	csrf VARCHAR(64) NOT NULL, 
	user_id INTEGER NOT NULL, 
	expires_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (token_hash), 
	FOREIGN KEY(user_id) REFERENCES users (id)
);

CREATE INDEX ix_sessions_user_id ON sessions (user_id);

CREATE TABLE grants (
	id SERIAL NOT NULL, 
	doc_id VARCHAR(32) NOT NULL, 
	user_id INTEGER NOT NULL, 
	level VARCHAR(4) NOT NULL, 
	granted_by INTEGER NOT NULL, 
	granted_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	revoked_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(doc_id) REFERENCES documents (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(granted_by) REFERENCES users (id)
);

CREATE INDEX ix_grants_user_id ON grants (user_id);

CREATE INDEX ix_grants_doc_id ON grants (doc_id);

CREATE UNIQUE INDEX uq_active_grant ON grants (doc_id, user_id) WHERE revoked_at IS NULL;

-- Append-only protection for the audit table (second layer after DB role grants):
CREATE OR REPLACE FUNCTION audit_immutable() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'audit is append-only'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS audit_no_mutation ON audit;
CREATE TRIGGER audit_no_mutation BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION audit_immutable();
DROP TRIGGER IF EXISTS audit_no_truncate ON audit;
CREATE TRIGGER audit_no_truncate BEFORE TRUNCATE ON audit FOR EACH STATEMENT EXECUTE FUNCTION audit_immutable();
